WITH base AS (SELECT id, customer_id, store_id, order_date, amount, shipping_fee, UPPER(channel) AS channel_upper FROM orders WHERE order_date >= TO_DATE('2024-02-23')) SELECT *, MIN(shipping_fee) OVER w_hist AS store_id_min_shipping_fee, LEAD(shipping_fee, 2) OVER (PARTITION BY store_id ORDER BY shipping_fee ASC, id ASC) AS next_shipping_fee, CUME_DIST() OVER (PARTITION BY customer_id ORDER BY shipping_fee DESC) AS shipping_fee_cume_dist, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY order_date DESC, id ASC) AS event_seq FROM base WINDOW w_hist AS (PARTITION BY store_id)
